mapper.select:
select distinct B.ADMIN_ID, B.USER_ID, B.DEPT_ID, B.ORGAN_ID, B.USERNAME, B.NAME, B.EMAIL, B.MOBILE, B.IS_SUPER_ADMIN, B.IS_AUDIT_ADMIN, B.IS_SELF_ADMIN, B.STATUS, B.CREATE_TIME from ADMIN_USER B left join ADMIN_DEPT DEPT on B.DEPT_ID = DEPT.DEPT_ID left join ADMIN_USER_ROLE AUR on B.ADMIN_ID = AUR.ADMIN_ID left join SYS_ROLE RO on RO.ROLE_ID = AUR.ROLE_ID where B.DEL_FLAG = 0 and RO.ROLE_ID = #{roleId}
AND B.USERNAME like concat('%', #{username}, '%')
AND B.MOBILE like concat('%', #{mobile}, '%')
